/// Represents the reading of an analog meter, pressure dial, or digital gauge.
class MeterReadingResult {
  /// The extracted numeric value (e.g. 14.2, 120.0). Null if unreadable.
  final double? numericValue;

  /// The unit of measurement (e.g. "psi", "bar", "kPa", "V"). Null if not specified or unreadable.
  final String? unit;

  /// True if the gauge dial/digits were clearly legible without ambiguity.
  /// False if the image was blurry, cut off, or triggered the UNREADABLE escape hatch.
  final bool isReadable;

  /// The verbatim raw output generated by the vision model.
  final String rawOutput;

  const MeterReadingResult({
    this.numericValue,
    this.unit,
    required this.isReadable,
    required this.rawOutput,
  });

  @override
  String toString() => isReadable
      ? 'MeterReadingResult($numericValue ${unit ?? ""})'
      : 'MeterReadingResult(UNREADABLE)';
}

/// Status of a rapid diagnostic lateral flow test strip (e.g. malaria, pregnancy, infectious disease).
enum TestStripStatus {
  /// Both Control (C) and Test (T) lines are visible (positive indication).
  positive,

  /// Only Control (C) line is visible; Test (T) line is absent (negative indication).
  negative,

  /// Control (C) line is missing or broken. The test strip is spoiled or invalid.
  invalid,

  /// The image is blurry, poorly lit, or ambiguous. The user should retake the photo.
  unclear,
}

/// Result of evaluating a rapid diagnostic test strip.
class TestStripResult {
  /// The classified status of the strip.
  final TestStripStatus status;

  /// True if the result is positive or negative with a valid control line.
  /// False if invalid or unclear, indicating the field worker should re-test or retake photo.
  bool get isReliable =>
      status == TestStripStatus.positive || status == TestStripStatus.negative;

  /// The verbatim raw output generated by the vision model.
  final String rawOutput;

  const TestStripResult({
    required this.status,
    required this.rawOutput,
  });

  @override
  String toString() => 'TestStripResult(status: ${status.name}, reliable: $isReliable)';
}

/// Result of agricultural leaf and plant symptom visual inspection.
class CropHealthResult {
  /// Name of the identified disease, pathogen, or "Healthy".
  final String condition;

  /// Whether the leaf displays no signs of disease or pest infestation.
  final bool isHealthy;

  /// True if diagnosis was made with confidence. False if photo was unclear or ambiguous.
  final bool isConfident;

  /// The verbatim raw output generated by the vision model.
  final String rawOutput;

  const CropHealthResult({
    required this.condition,
    required this.isHealthy,
    required this.isConfident,
    required this.rawOutput,
  });

  @override
  String toString() =>
      'CropHealthResult(condition: $condition, isHealthy: $isHealthy, isConfident: $isConfident)';
}

/// Result of structured field extraction from an inspection sheet, label, or checklist.
class InspectionDocResult {
  /// Key-value attributes extracted from the document.
  final Map<String, String> extractedFields;

  /// High-level summary of the inspection report.
  final String summary;

  /// True if the document was legible and fields were successfully extracted.
  final bool isLegible;

  /// The verbatim raw output generated by the vision model.
  final String rawOutput;

  const InspectionDocResult({
    required this.extractedFields,
    required this.summary,
    required this.isLegible,
    required this.rawOutput,
  });

  @override
  String toString() =>
      'InspectionDocResult(isLegible: $isLegible, fields: ${extractedFields.length})';
}
